info.description:
transparent search bar@-moz-document domain("google.com") {
    /* Targets the main search container wrapper */
    .gLFyf, .RNNXgb, .SDkEP {
        background-color: transparent !important;
        background: transparent !important;
        box-shadow: none !important;
        border: 1px solid rgba(255, 255, 255, 0.2) !important; /* Optional faint border */
    }

    /* Keeps it transparent even when hovering or typing */
    .RNNXgb:hover, .extbar, .aa-dropdown-menu {
        background-color: transparent !important;
        box-shadow: none !important;
    }
}

